    paper: '#FFFDF7',
    ink: '#2B3118',
    olive: '#6E8B1F',
    oliveDark: '#4F6516',
    lime: '#C4D34E',
    orange: '#E8843A',
    amber: '#F2B33D',
    pink: '#F2A7A5',
