/**
 * Materiales toon (sombreado por bandas, look "ilustración")
 */
let gradientMap = null
const materialCache = new Map()

function getGradientMap()
{
    if(!gradientMap)
    {
        const data = new Uint8Array([ 120, 195, 255 ])
        gradientMap = new THREE.DataTexture(data, 3, 1, THREE.RedFormat)
        gradientMap.minFilter = THREE.NearestFilter
        gradientMap.magFilter = THREE.NearestFilter
        gradientMap.generateMipmaps = false
        gradientMap.needsUpdate = true
    }
    return gradientMap
}

export function toon(color, options = {})
{
    const key = color + JSON.stringify(options)
    if(!materialCache.has(key))
    {
        materialCache.set(key, new THREE.MeshToonMaterial({ color, gradientMap: getGradientMap(), ...options }))
    }
    return materialCache.get(key)
}

/**
 * Contorno tipo caricatura: una copia de la malla, un poco más grande, con las caras invertidas
 */
export function addOutline(mesh, color = palette.orange, scale = 1.07)
{
    const outline = new THREE.Mesh(
        mesh.geometry,
        new THREE.MeshBasicMaterial({ color, side: THREE.BackSide })
    )
    outline.scale.setScalar(scale)
    mesh.add(outline)
    return outline
}

/**
 * Aleatorio con semilla (para que el mundo sea siempre igual)
 */
export function rngFrom(seed = 1)
{
    let a = seed >>> 0
    return () =>
    {
        a |= 0
        a = a + 0x6D2B79F5 | 0
        let t = Math.imul(a ^ a >>> 15, 1 | a)
        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t
        return ((t ^ t >>> 14) >>> 0) / 4294967296
    }
}

const pick = (rng, list) => list[Math.floor(rng() * list.length)]

/**
 * Árbol simple: tronco + copa (cono o bola)
 */
export function createTree(rng)
{
    const tree = new THREE.Group()
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.07, 0.3, 6), toon(palette.rockDark))
    trunk.position.y = 0.15
    tree.add(trunk)

    const crownColor = pick(rng, [ palette.olive, palette.olive, palette.lime ])
    if(rng() > 0.45)
    {
        const crown = new THREE.Mesh(new THREE.ConeGeometry(0.28, 0.75, 7), toon(crownColor))
        crown.position.y = 0.3 + 0.37
        tree.add(crown)
    }
    else
    {
        const crown = new THREE.Mesh(new THREE.IcosahedronGeometry(0.3, 0), toon(crownColor))
        crown.position.y = 0.3 + 0.24
        tree.add(crown)
    }
    tree.scale.setScalar(0.7 + rng() * 0.6)
    return tree
}

/**
 * Isla flotante (como las del moodboard): tapa de pasto + roca en punta.
 * La superficie superior queda en y = 0.
 */
export function createIsland(rng, { radius = 1.5, top = palette.lime, rock = palette.rock, trees = 3 } = {})
{
    const island = new THREE.Group()
    const sides = 7
    const twist = rng() * Math.PI * 2

    const grass = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius * 0.94, 0.32, sides), toon(top))
    grass.position.y = -0.16
    grass.rotation.y = twist
    island.add(grass)

    const band = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.94, radius * 0.86, 0.28, sides), toon(palette.rockDark))
    band.position.y = -0.46
    band.rotation.y = twist
    island.add(band)

    const rockHeight = radius * 1.5
    const stone = new THREE.Mesh(new THREE.ConeGeometry(radius * 0.86, rockHeight, sides), toon(rock))
    stone.rotation.x = Math.PI
    stone.rotation.y = twist
    stone.position.y = -0.6 - rockHeight / 2
    island.add(stone)

    for(let i = 0; i < trees; i++)
    {
        const angle = rng() * Math.PI * 2
        const r = radius * (0.2 + rng() * 0.55)
        const tree = createTree(rng)
        tree.position.set(Math.cos(angle) * r, 0, Math.sin(angle) * r)
        island.add(tree)
    }

    island.userData.bottom = -0.6 - rockHeight
    return island
}

/**
 * Nube 3D de bolitas
 */
export function createCloud(rng, size = 1)
{
    const cloud = new THREE.Group()
    const material = toon(palette.white)
    const puffs = 4 + Math.floor(rng() * 3)
    for(let i = 0; i < puffs; i++)
    {
        const r = (0.45 + rng() * 0.45) * size
        const puff = new THREE.Mesh(new THREE.SphereGeometry(r, 14, 10), material)
        puff.position.set((i - puffs / 2) * 0.55 * size, rng() * 0.3 * size, (rng() - 0.5) * 0.4 * size)
        cloud.add(puff)
    }
    return cloud
}

/**
 * Objetos de las 3 islas del menú
 */
export function buildLugares(island)
{
    // Una pequeña "Ermita": nave, techo y torre con aguja
    const ermita = new THREE.Group()
    const wall = toon('#FFF6EC')
    const roof = toon(palette.pink)

    const nave = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.85, 0.8), wall)
    nave.position.y = 0.425
    ermita.add(nave)

    const naveRoof = new THREE.Mesh(new THREE.ConeGeometry(0.72, 0.5, 4), roof)
    naveRoof.rotation.y = Math.PI / 4
    naveRoof.scale.z = 0.82
    naveRoof.position.y = 0.85 + 0.25
    ermita.add(naveRoof)

    const tower = new THREE.Mesh(new THREE.BoxGeometry(0.34, 1.55, 0.34), wall)
    tower.position.set(0, 0.775, 0.5)
    ermita.add(tower)

    const spire = new THREE.Mesh(new THREE.ConeGeometry(0.27, 0.8, 4), roof)
    spire.rotation.y = Math.PI / 4
    spire.position.set(0, 1.55 + 0.4, 0.5)
    ermita.add(spire)

    const door = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.26, 0.02), toon(palette.rockDark))
    door.position.set(0, 0.13, 0.675)
    ermita.add(door)

    ermita.position.set(-0.85, 0, -0.75)
    ermita.rotation.y = 0.35
    island.add(ermita)

    // Pin de mapa flotando
    const pin = new THREE.Group()
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.22, 18, 14), toon(palette.orange))
    head.position.y = 0.3
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.42, 18), toon(palette.orange))
    tip.rotation.x = Math.PI
    tip.position.y = 0.06
    const dot = new THREE.Mesh(new THREE.SphereGeometry(0.08, 12, 10), toon(palette.paper))
    dot.position.set(0, 0.32, 0.17)
    pin.add(head, tip, dot)
    pin.position.set(0.95, 1.9, -0.5)
    island.add(pin)
    island.userData.floaty = pin
}

export function buildRutas(island, rng)
{
    // Camino serpenteante de baldosas
    const tile = toon(palette.amber)
    const steps = 9
    for(let i = 0; i < steps; i++)
    {
        const t = i / (steps - 1)
        const x = -1.45 + t * 2.8
        const z = Math.sin(t * Math.PI * 1.6) * 0.75
        const piece = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.05, 0.34), tile)
        piece.position.set(x, 0.025, z)
        piece.rotation.y = t * 1.5
        island.add(piece)
    }

    // Banderita al final
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 1.2, 8), toon(palette.ink))
    pole.position.set(1.35, 0.6, -0.95)
    island.add(pole)

    const shape = new THREE.Shape()
    shape.moveTo(0, 0)
    shape.lineTo(0.55, -0.16)
    shape.lineTo(0, -0.34)
    shape.lineTo(0, 0)
    const flag = new THREE.Mesh(new THREE.ShapeGeometry(shape), toon(palette.orange, { side: THREE.DoubleSide }))
    flag.position.set(1.36, 1.18, -0.95)
    island.add(flag)
    island.userData.flag = flag

    for(let i = 0; i < 3; i++)
    {
        const tree = createTree(rng)
        const a = -2.2 + i * 1.3
        tree.position.set(Math.cos(a) * 1.45, 0, Math.sin(a) * 1.2 - 0.3)
        island.add(tree)
    }
}

export function buildEventos(island)
{
    // Tarima + telón + guirnalda de luces
    const stage = new THREE.Mesh(new THREE.BoxGeometry(1.7, 0.24, 0.9), toon(palette.amber))
    stage.position.set(0.15, 0.12, -0.85)
    island.add(stage)

    const backdrop = new THREE.Mesh(new THREE.BoxGeometry(1.7, 1.05, 0.08), toon(palette.orange))
    backdrop.position.set(0.15, 0.77, -1.26)
    island.add(backdrop)

    const star = new THREE.Mesh(new THREE.OctahedronGeometry(0.2, 0), toon(palette.paper))
    star.position.set(0.15, 0.82, -1.18)
    island.add(star)
    island.userData.floaty = star

    const poleMat = toon(palette.ink)
    const left = new THREE.Vector3(-1.45, 1.35, 0.25)
    const right = new THREE.Vector3(1.5, 1.35, 0.25)
    for(const p of [ left, right ])
    {
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, p.y, 8), poleMat)
        pole.position.set(p.x, p.y / 2, p.z)
        island.add(pole)
    }

    const bulbColors = [ palette.pink, palette.amber, palette.lime, palette.paper ]
    const bulbs = []
    const count = 9
    for(let i = 0; i < count; i++)
    {
        const t = (i + 1) / (count + 1)
        const p = new THREE.Vector3().lerpVectors(left, right, t)
        p.y -= Math.sin(t * Math.PI) * 0.45
        const bulb = new THREE.Mesh(
            new THREE.SphereGeometry(0.075, 12, 10),
            new THREE.MeshBasicMaterial({ color: bulbColors[i % bulbColors.length] })
        )
        bulb.position.copy(p)
        island.add(bulb)
        bulbs.push(bulb)
    }
    island.userData.bulbs = bulbs
}

/**
 * El Bulevar 3D: una interpretación abstracta y flotante del recorrido real,
 * con río, puentes, edificios reinterpretados, vegetación y puntos interactivos
 * para cada categoría (lugares, eventos). Las rutas se arman conectando estos
 * mismos puntos.
 */
export function createBulevarWorld(rng, pointsData = [])
{
    const group = new THREE.Group()
    const RX = 6.6
    const RZ = 3.1

    const platform = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 0.4, 56), toon(palette.lime))
    platform.scale.set(RX, 1, RZ)
    platform.position.y = -0.2
    group.add(platform)

    const band = new THREE.Mesh(new THREE.CylinderGeometry(1, 0.9, 0.5, 56), toon(palette.rockDark))
    band.scale.set(RX * 0.97, 1, RZ * 0.97)
    band.position.y = -0.62
    group.add(band)

    const keel = new THREE.Mesh(new THREE.ConeGeometry(1, 3.4, 56), toon(palette.rock))
    keel.rotation.x = Math.PI
    keel.scale.set(RX * 0.82, 1, RZ * 0.82)
    keel.position.y = -0.62 - 1.7
    group.add(keel)

    // Río que atraviesa el bulevar
    const river = new THREE.Mesh(new THREE.BoxGeometry(RX * 1.94, 0.09, 1.15), toon(palette.river))
    river.position.set(0, 0.005, 0.55)
    group.add(river)
    const riverEdge = new THREE.Mesh(new THREE.BoxGeometry(RX * 2, 0.04, 1.3), toon(palette.riverDark))
    riverEdge.position.set(0, -0.03, 0.55)
    group.add(riverEdge)

    // Puentes
    function bridge(x)
    {
        const b = new THREE.Group()
        const deck = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.08, 1.5), toon(palette.stone))
        deck.position.y = 0.13
        b.add(deck)
        for(const side of [ -1, 1 ])
        {
            const rail = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.16, 0.045), toon(palette.stoneDark))
            rail.position.set(0, 0.24, side * 0.73)
            b.add(rail)
        }
        b.position.set(x, 0, 0.55)
        return b
    }
    group.add(bridge(0))

    // Edificios reinterpretados (arquitectura del centro histórico, en abstracto).
    // Pocos y con propósito: marcan los dos extremos del bulevar, nada más.
    function building({ x, z, w, h, d, color, roof })
    {
        const b = new THREE.Group()
        const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), toon(color))
        body.position.y = h / 2
        b.add(body)
        if(roof)
        {
            const r = new THREE.Mesh(new THREE.ConeGeometry(Math.max(w, d) * 0.72, h * 0.5, 4), toon(palette.pink))
            r.rotation.y = Math.PI / 4
            r.position.y = h + h * 0.25
            b.add(r)
        }
        b.position.set(x, 0, z)
        return b
    }
    group.add(building({ x: -4.9, z: -1.5, w: 1.15, h: 1.3, d: 0.95, color: '#FFF6EC', roof: true }))
    group.add(building({ x: 5.0, z: -1.4, w: 1.5, h: 1.1, d: 1.05, color: palette.stone, roof: false }))

    // Vegetación: unos pocos árboles, no un bosque
    for(let i = 0; i < 6; i++)
    {
        const tree = createTree(rng)
        const x = lerp(-RX + 1, RX - 1, i / 5)
        const side = rng() > 0.5 ? 1 : -1
        const z = side * (1.4 + rng() * 1.4)
        tree.position.set(x, 0, z)
        tree.rotation.y = rng() * Math.PI * 2
        tree.scale.setScalar(0.6 + rng() * 0.4)
        group.add(tree)
    }

    // Farolas: solo un par, junto al puente
    function lamp(x, z)
    {
        const l = new THREE.Group()
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.9, 8), toon(palette.ink))
        pole.position.y = 0.45
        l.add(pole)
        const globe = new THREE.Mesh(new THREE.SphereGeometry(0.09, 12, 10), new THREE.MeshBasicMaterial({ color: palette.amber }))
        globe.position.y = 0.92
        l.add(globe)
        l.position.set(x, 0, z)
        l.userData.globe = globe
        return l
    }
    const lamps = [ lamp(-1.6, 1.05), lamp(1.6, 1.05) ]
    group.add(...lamps)

    // Puntos interactivos: uno por cada lugar / evento
    function lerp(a, b, t) { return a + (b - a) * t }
    function makePin(data, x, z)
    {
        const pin = new THREE.Group()
        const mat = new THREE.MeshBasicMaterial({ color: data.color })
        const head = new THREE.Mesh(new THREE.SphereGeometry(0.16, 16, 12), mat)
        head.position.y = 0.86
        pin.add(head)
        const tip = new THREE.Mesh(new THREE.ConeGeometry(0.14, 0.3, 16), mat)
        tip.rotation.x = Math.PI
        tip.position.y = 0.63
        pin.add(tip)
        const ring = new THREE.Mesh(
            new THREE.RingGeometry(0.22, 0.3, 24),
            new THREE.MeshBasicMaterial({ color: data.color, transparent: true, opacity: 0.55, side: THREE.DoubleSide })
        )
        ring.rotation.x = -Math.PI / 2
        ring.position.y = 0.02
        pin.add(ring)
        const glow = new THREE.Mesh(
            new THREE.CircleGeometry(0.55, 24),
            new THREE.MeshBasicMaterial({ color: data.color, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false })
        )
        glow.rotation.x = -Math.PI / 2
        glow.position.y = 0.015
        pin.add(glow)
        pin.position.set(x, 0, z)
        pin.userData = { id: data.id, category: data.category, baseY: 0.86, head, tip, ring, glow, phase: rng() * Math.PI * 2 }
        return pin
    }

    const n = Math.max(pointsData.length, 1)
    const pins = pointsData.map((data, i) =>
    {
        const angle = (i / n) * Math.PI * 2 - Math.PI / 2
        const x = Math.cos(angle) * (RX - 1.1)
        const z = Math.sin(angle) * (RZ + 1.75)
        const pin = makePin(data, x, z)
        group.add(pin)
        return pin
    })

    return { group, pins, lamps }
}
