import * as THREE from 'three'
import { palette, toon, addOutline } from './world.js'

/**
 * Personaje: Don Chontaduro, con la cabeza triangular característica del
 * fruto (ancha arriba, angosta abajo), su corona de pétalos y el cuerno
 * curvo en la punta.
 *
 * Jerarquía:
 *  root   -> posición en el mundo + hacia dónde mira (rotation.y)
 *  pivot  -> rebote al caminar y aplastamiento al aterrizar (origen en los pies)
 *  look   -> inclinación del cuerpo (mirar arriba / abajo)
 */
export function createCharacter()
{
    const root = new THREE.Group()
    const pivot = new THREE.Group()
    root.add(pivot)

    const look = new THREE.Group()
    look.position.y = 0.4
    pivot.add(look)

    const skin = toon(palette.chontaduroLight)

    // Cuerpo: un cilindro redondeado, como en la referencia
    const bodyGeometry = new THREE.CapsuleGeometry(0.2, 0.3, 6, 14)
    const body = new THREE.Mesh(bodyGeometry, skin)
    body.position.y = 0.35
    addOutline(body, palette.chontaduroDark, 1.08)
    look.add(body)

    // Cabeza: una sola silueta tallada por revolución (Lathe), ancha arriba y
    // angosta hacia el cuerpo, con degradado de rojo a naranja como el fruto.
    const head = new THREE.Group()
    head.position.y = 0.56
    look.add(head)

    const HEAD_TOP = 0.88
    const headProfile = [
        [ 0.17, 0.00 ],
        [ 0.19, 0.08 ],
        [ 0.25, 0.22 ],
        [ 0.33, 0.38 ],
        [ 0.39, 0.52 ],
        [ 0.40, 0.60 ],
        [ 0.36, 0.70 ],
        [ 0.24, 0.80 ],
        [ 0.08, 0.86 ],
        [ 0.00, HEAD_TOP ]
    ].map(([ x, y ]) => new THREE.Vector2(x, y))
    const headGeometry = new THREE.LatheGeometry(headProfile, 24)

    const gradTop = new THREE.Color(palette.chontaduro)
    const gradBottom = new THREE.Color(palette.chontaduroLight)
    const tmpColor = new THREE.Color()
    const headPos = headGeometry.attributes.position
    const headColors = new Float32Array(headPos.count * 3)
    for(let i = 0; i < headPos.count; i++)
    {
        const t = THREE.MathUtils.clamp(headPos.getY(i) / HEAD_TOP, 0, 1)
        tmpColor.copy(gradBottom).lerp(gradTop, t)
        headColors.set([ tmpColor.r, tmpColor.g, tmpColor.b ], i * 3)
    }
    headGeometry.setAttribute('color', new THREE.BufferAttribute(headColors, 3))

    const headMesh = new THREE.Mesh(headGeometry, toon('#FFFFFF', { vertexColors: true }))
    addOutline(headMesh, palette.chontaduroDark, 1.04)
    head.add(headMesh)

    // Cara: en la zona naranja de la cabeza, bajo el remate rojo
    const face = new THREE.Group()
    face.position.y = 0.3
    head.add(face)

    const eyeMaterial = toon(palette.ink)
    const eyes = []
    for(const side of [ -1, 1 ])
    {
        const eye = new THREE.Mesh(new THREE.CapsuleGeometry(0.04, 0.05, 4, 8), eyeMaterial)
        eye.position.set(side * 0.13, 0.02, 0.27)
        eye.scale.z = 0.45
        face.add(eye)
        eyes.push(eye)
    }

    const mouth = new THREE.Mesh(new THREE.SphereGeometry(0.048, 14, 10), eyeMaterial)
    mouth.scale.set(1.15, 0.9, 0.35)
    mouth.position.set(0, -0.14, 0.19)
    face.add(mouth)

    const cheekMaterial = new THREE.MeshBasicMaterial({ color: palette.chontaduroCheek })
    for(const side of [ -1, 1 ])
    {
        const cheek = new THREE.Mesh(new THREE.CircleGeometry(0.055, 18), cheekMaterial)
        cheek.position.set(side * 0.2, -0.06, 0.24)
        cheek.rotation.y = side * 0.6
        face.add(cheek)
    }

    // Corona: pétalos del cáliz + el cuerno curvo característico
    const sprout = new THREE.Group()
    sprout.position.y = HEAD_TOP - 0.04
    head.add(sprout)

    const petalMaterial = toon(palette.chontaduroPetal)
    const petalCount = 6
    for(let i = 0; i < petalCount; i++)
    {
        const angle = (i / petalCount) * Math.PI * 2
        const petal = new THREE.Mesh(new THREE.SphereGeometry(0.1, 10, 8), petalMaterial)
        petal.scale.set(0.7, 1.3, 0.4)
        petal.position.set(Math.cos(angle) * 0.1, 0.02, Math.sin(angle) * 0.1)
        petal.rotation.z = Math.cos(angle) * 0.9
        petal.rotation.x = -Math.sin(angle) * 0.9
        sprout.add(petal)
    }

    const hornCurve = new THREE.CatmullRomCurve3([
        new THREE.Vector3(0, 0, 0),
        new THREE.Vector3(0.02, 0.1, 0),
        new THREE.Vector3(0.09, 0.18, -0.01),
        new THREE.Vector3(0.14, 0.23, -0.04)
    ])
    const horn = new THREE.Mesh(new THREE.TubeGeometry(hornCurve, 12, 0.026, 8, false), toon(palette.chontaduroHorn))
    sprout.add(horn)

    // Brazos: cilindros simples que cuelgan casi rectos (dentro de "look"
    // para que se inclinen con el cuerpo)
    const limbGeometry = new THREE.CapsuleGeometry(0.055, 0.2, 6, 12)
    const arms = []
    for(const side of [ -1, 1 ])
    {
        const shoulder = new THREE.Group()
        shoulder.position.set(side * 0.22, 0.42, 0)
        shoulder.rotation.z = side * 0.12
        const arm = new THREE.Mesh(limbGeometry, skin)
        arm.position.y = -0.17
        addOutline(arm, palette.chontaduroDark, 1.18)
        shoulder.add(arm)
        look.add(shoulder)
        shoulder.userData.side = side
        arms.push(shoulder)
    }

    // Piernas: cilindros cortos y simples, sin pies (en "pivot" para que no
    // se inclinen)
    const legGeometry = new THREE.CapsuleGeometry(0.075, 0.16, 6, 12)
    const legs = []
    for(const side of [ -1, 1 ])
    {
        const hip = new THREE.Group()
        hip.position.set(side * 0.1, 0.19, 0)
        const leg = new THREE.Mesh(legGeometry, skin)
        leg.position.y = -0.17
        addOutline(leg, palette.chontaduroDark, 1.14)
        hip.add(leg)
        pivot.add(hip)
        legs.push(hip)
    }

    return { root, pivot, look, arms, legs, eyes, sprout }
}
