// Marcadores de cada hito: un anillo sobre el haz + una señal hacia la tarjeta.
// Todas las tarjetas quedan del mismo lado (derecha), opuesto al chontaduro.
const markers = hitos.map((hito, i) =>
{
    const side = 1
    const cardX = side * CARD_X
    const marker = new THREE.Group()
    marker.position.set(0, hitoY[i], MARKER_Z)

    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.34, 0.045, 10, 28), toon(hito.color))
    ring.rotation.x = -Math.PI / 2
    marker.add(ring)

    const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.028, Math.abs(cardX) * 0.72, 8), toon(palette.oliveDark))
    arm.rotation.z = Math.PI / 2
    arm.position.x = cardX * 0.36
    marker.add(arm)

    const knob = new THREE.Mesh(new THREE.SphereGeometry(0.13, 18, 14), toon(hito.color))
    knob.position.set(cardX * 0.72, 0.06, 0)
    marker.add(knob)

    marker.userData.side = side
    marker.userData.knob = knob
    marker.scale.setScalar(0.0001)
    scene.add(marker)
    return marker
})
