/**
 * Decoración: solo nubes flotando durante el recorrido, nada de islas de fondo
 */
const decor = []
function scatterClouds(count, xMin, xMax, yMin, yMax, zMin, zMax, size = 1)
{
    for(let i = 0; i < count; i++)
    {
        const cloud = createCloud(rng, size * (0.7 + rng() * 0.8))
        cloud.position.set(lerp(xMin, xMax, rng()), lerp(yMin, yMax, rng()), lerp(zMin, zMax, rng()))
        cloud.userData.baseX = cloud.position.x
        cloud.userData.phase = rng() * Math.PI * 2
        scene.add(cloud)
        decor.push(cloud)
    }
}
