let routeLine = null
function updateRouteLine(stopIds)
{
    if(routeLine) { bulevar.group.remove(routeLine); routeLine.geometry.dispose(); routeLine = null }
    if(stopIds.length < 2) return
    const positions = []
    for(const id of stopIds)
    {
        const pin = bulevar.pins.find((p) => p.userData.id === id)
        if(!pin) continue
        positions.push(pin.position.x, 0.08, pin.position.z)
    }
    const geometry = new THREE.BufferGeometry()
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
    routeLine = new THREE.Line(geometry, new THREE.LineBasicMaterial({ color: palette.paper, transparent: true, opacity: 0.9 }))
    bulevar.group.add(routeLine)
}

