/**
 * Tamaños, cámara y encuadres
 */
const sizes = { width: window.innerWidth, height: window.innerHeight }
const camera = new THREE.PerspectiveCamera(35, sizes.width / sizes.height, 0.1, 200)
scene.add(camera)

const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true })
renderer.setClearColor(0x000000, 0)

const framing = { dist: 12, halfW: 6, offset: 3, trioDist: 14, worldDist: 20 }

function resize()
{
    sizes.width = window.innerWidth
    sizes.height = window.innerHeight
    const aspect = sizes.width / sizes.height

    camera.aspect = aspect
    camera.updateProjectionMatrix()
    renderer.setSize(sizes.width, sizes.height)
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))

    const tanHalf = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2))

    // Encuadre de la carga: personaje en el tercio derecho, caminando en horizontal
    framing.dist = Math.max(3.7 / tanHalf, 3.3 / (tanHalf * aspect))
    framing.halfW = framing.dist * tanHalf * aspect
    framing.offset = Math.min(3.2, framing.halfW * 0.46)

    // Encuadre de la línea de tiempo: el chontaduro a la izquierda, la línea y
    // las tarjetas a la derecha deben caber las dos
    framing.readDist = Math.max(3.9 / tanHalf, 4.6 / (tanHalf * aspect))

    // Encuadre del trío inicial (Lugares / Eventos / Rutas): que quepan los tres
    framing.trioDist = Math.max(6.4 / tanHalf, 8.6 / (tanHalf * aspect))
    // Encuadre del Bulevar 3D explorable
    framing.worldDist = Math.max(7 / tanHalf, 10 / (tanHalf * aspect))

    for(const card of cards)
    {
        card.width = card.el.offsetWidth
        card.height = card.el.offsetHeight
    }
    const cloudBase = Math.max(sizes.width, sizes.height)
    for(const cloud of clouds2D)
    {
        cloud.w = cloudBase * cloud.size
        cloud.h = cloud.w * 0.6
        cloud.el.style.width = `${cloud.w}px`
    }

    if(mode === 'loading' && !loaderStarted)
    {
        state.loaderX = framing.offset + framing.halfW + 1.6
    }
}

/**
 * Estado (lo animan GSAP y el scroll)
 */
const state = {
    loaderX: 10,
    intro: 0,
    travel: 0,   // baja por la línea de tiempo
    edge: 0,     // sigue bajando... al borde
    look: 0,     // mira hacia abajo
    fall: 0,     // cae
    cover: 0,    // las nubes lo tapan
    reveal: 0    // las nubes se van y aparecen los tres Bulevares
}
const worldState = { enter: 0 }
let mode = 'loading'
let loaderStarted = false

window.addEventListener('resize', resize)
resize()
document.fonts?.ready.then(resize)

/**
 * 1. Pantalla de carga: camina de derecha a izquierda
 */
function startLoader()
{
    loaderStarted = true
    gsap.to(state, {
        loaderX: CHAR_X,
        duration: reduceMotion ? 1.6 : 4,
        ease: 'none',
        onUpdate()
        {
            loaderPctEl.textContent = Math.round(this.progress() * 100)
        },
        onComplete: finishLoader
    })
}

function finishLoader()
{
    mode = 'timeline'
    const tl = gsap.timeline()
    tl.to(whiteEl, { opacity: 0, duration: 1.2, ease: 'power2.inOut' }, 0)
    tl.to(loaderEl, { opacity: 0, y: 20, duration: 0.6, ease: 'power2.in' }, 0)
    tl.to(line.scale, { y: 1, duration: 2.4, ease: 'power2.out' }, 0.4)
    decor.forEach((item) =>
    {
        tl.to(item.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'back.out(1.7)' }, 0.3 + Math.random() * 1.2)
    })
    tl.to(state, { intro: 1, duration: 0.9, ease: 'power1.out' }, 1)
    tl.add(() =>
    {
        document.documentElement.classList.remove('is-loading')
        whiteEl.style.display = 'none'
        setupScroll()
    }, 1.2)
}

/**
 * 2. Scroll: línea de tiempo (vertical) → borde → caída → nubes → tres Bulevares
 */
function setupScroll()
{
    const tl = gsap.timeline({
        defaults: { ease: 'none' },
        scrollTrigger: {
            trigger: '.scroll-space',
            start: 'top top',
            end: 'bottom bottom',
            scrub: 1
        }
    })

    tl.to(state, { travel: 1, duration: 7 })
    tl.to(state, { edge: 1, duration: 0.6, ease: 'power1.inOut' })
    tl.to(state, { look: 1, duration: 0.6 })
    tl.to(state, { fall: 1, duration: 1.1, ease: 'power2.in' }, '+=0.1')
    tl.to(state, { cover: 1, duration: 0.7, ease: 'power1.out' }, '<0.35')
    tl.to(state, { reveal: 1, duration: 1.2 }, '>0.15')
    tl.to({}, { duration: 0.4 })

    ScrollTrigger.refresh()
}

