const TRIO_LAYOUT = [ [ 0, 2.3 ], [ -3.3, -1.9 ], [ 3.3, -1.9 ] ]
let trio = null
let trioHoverIndex = -1

function spawnTrio(items, anchor, { eyebrow, heading, radius = 1.9 }, onSelect)
{
    trioEyebrowEl.textContent = eyebrow
    trioHeadingEl.textContent = heading
    trioLabelsEl.innerHTML = ''

    const group = new THREE.Group()
    group.position.set(anchor.x, anchor.y, 0)
    scene.add(group)

    const labelEls = []
    const islands = items.map((item, i) =>
    {
        const island = createIsland(rng, { radius, trees: 0, top: palette.lime, rock: item.rock })
        item.decorate?.(island, rng)
        island.position.set(TRIO_LAYOUT[i][0], TRIO_LAYOUT[i][1], 0)
        island.userData.trioIndex = i
        island.userData.hover = 0
        island.scale.setScalar(0.0001)
        group.add(island)
        gsap.to(island.scale, { x: 1, y: 1, z: 1, duration: 0.9, delay: 0.18 * i, ease: 'back.out(1.6)' })

        const label = document.createElement('span')
        label.className = 'trio-label'
        label.textContent = item.name
        trioLabelsEl.appendChild(label)
        labelEls.push(label)
        return island
    })

    trio = { group, islands, items, labelEls, onSelect, resolved: false }
}

function resolveTrio(index)
{
    if(!trio || trio.resolved) return
    trio.resolved = true
    const chosen = trio.items[index]
    const callback = trio.onSelect
    const finished = trio

    finished.islands.forEach((island, i) =>
    {
        if(i === index)
        {
            gsap.to(island.scale, { x: 2.6, y: 2.6, z: 2.6, duration: 1.05, ease: 'power2.inOut' })
        }
        else
        {
            gsap.to(island.scale, { x: 0.0001, y: 0.0001, z: 0.0001, duration: 0.65, ease: 'power1.in' })
            gsap.to(island.position, { x: island.position.x * 2.4, y: island.position.y - 2.4, duration: 0.65, ease: 'power1.in' })
        }
    })
    trioEl.classList.remove('is-on')
    trioHoverIndex = -1

    gsap.delayedCall(1, () =>
    {
        scene.remove(finished.group)
        finished.group.traverse((child) => { if(child.isMesh) child.geometry.dispose() })
        if(trio === finished) trio = null
        callback(chosen.id)
    })
}

/**
 * 4. Dentro del Bulevar: la categoría elegida en el trío, tarjetas y rutas
 */
let insideBulevar = false
let activeCategory = null
let selectedPinId = null
let pinHoverId = null
let buildingRoute = false
let routeStops = []
const WALL_KEY = 'bulevar-diverso-muro'

function enterCategory(key)
{
    insideBulevar = true
    activeCategory = key
    buildingRoute = false
    const chosen = CATEGORY_CHOICES.find((c) => c.id === key) || CATEGORY_CHOICES[0]

    if(bulevar.group.scale.x < 0.01)
    {
        worldRotY = chosen.startAngle
        gsap.to(bulevar.group.scale, { x: 1, y: 1, z: 1, duration: 1.3, ease: 'back.out(1.3)' })
    }
    gsap.to(worldState, { enter: 1, duration: 1.4, ease: 'power2.inOut' })
    subnavEl.classList.add('is-on')
    worldTintEl.style.backgroundColor = `rgba(${CATEGORY_META[key].tint}, 1)`
    worldTintEl.classList.add('is-on')
    closeCard()

    if(key === 'rutas')
    {
        worldHintEl.textContent = 'Toca cualquier punto y usa "Agregar a ruta" para conectar tu recorrido'
        worldListEl.innerHTML = ''
        for(const cat of rutaCategorias)
        {
            const li = document.createElement('li')
            li.className = 'world-item'
            li.style.setProperty('--c', cat.color)
            li.innerHTML = `<strong>${cat.name}</strong><span>${cat.short}</span>`
            worldListEl.appendChild(li)
        }
        worldCtaEl.hidden = false
        worldEl.classList.add('is-on')
        renderRouteStops()
    }
    else
    {
        // Lugares / Eventos: los puntos ya están sobre el Bulevar, sin lista
        worldHintEl.textContent = 'Arrastra para girar el bulevar · Toca un punto para descubrirlo'
        worldEl.classList.remove('is-on')
        routebarEl.classList.remove('is-on')
        shareFabEl.classList.remove('is-on')
    }
}

function renderRouteStops()
{
    routeStopsEl.innerHTML = ''
    for(const id of routeStops)
    {
        const data = pointById.get(id)
        if(!data) continue
        const li = document.createElement('li')
        li.textContent = data.name
        routeStopsEl.appendChild(li)
    }
    routebarEmptyEl.hidden = routeStops.length > 0
    routebarEl.classList.toggle('is-on', activeCategory === 'rutas')
    shareFabEl.classList.toggle('is-on', activeCategory === 'rutas' && routeStops.length >= 2)
}

function selectPin(id)
{
    const data = pointById.get(id)
    if(!data) return
    selectedPinId = id
    const pin = bulevar.pins.find((p) => p.userData.id === id)
    if(pin) worldFocusRotY = -Math.atan2(pin.position.x, pin.position.z)
    card3dEl.style.setProperty('--c', data.color)
    card3dTagEl.textContent = data.tag
    card3dTitleEl.textContent = data.name
    card3dTextEl.textContent = data.short
    card3dAddEl.hidden = false
    const added = routeStops.includes(id)
    card3dAddEl.classList.toggle('is-added', added)
    card3dAddEl.textContent = added ? '✓ En tu ruta' : '+ Agregar a ruta'
    card3dEl.classList.add('is-on')
}

function closeCard()
{
    selectedPinId = null
    worldFocusRotY = null
    card3dEl.classList.remove('is-on')
}

function showConfirm()
{
    confirmTextEl.textContent = '¿Ver otra cosa por aquí?'
    confirmEl.classList.add('is-on')
}
function hideConfirm() { confirmEl.classList.remove('is-on') }

card3dCloseEl.addEventListener('click', closeCard)
card3dAnotherEl.addEventListener('click', closeCard)
card3dExitEl.addEventListener('click', () => { closeCard(); hideConfirm() })
card3dAddEl.addEventListener('click', () =>
{
    if(!selectedPinId) return
    const i = routeStops.indexOf(selectedPinId)
    if(i >= 0) routeStops.splice(i, 1)
    else routeStops.push(selectedPinId)
    updateRouteLine(routeStops)
    renderRouteStops()
    const added = routeStops.includes(selectedPinId)
    card3dAddEl.classList.toggle('is-added', added)
    card3dAddEl.textContent = added ? '✓ En tu ruta' : '+ Agregar a ruta'
})

confirmYesEl.addEventListener('click', hideConfirm)
confirmNoEl.addEventListener('click', hideConfirm)

worldCtaYesEl.addEventListener('click', () =>
{
    buildingRoute = true
    renderRouteStops()
})

routeResetEl.addEventListener('click', () =>
{
    routeStops = []
    buildingRoute = true
    updateRouteLine(routeStops)
    renderRouteStops()
})

function loadWall()
{
    try { return JSON.parse(localStorage.getItem(WALL_KEY)) || [] } catch(error) { return [] }
}
function saveWallEntry(entry)
{
    const list = loadWall()
    list.unshift(entry)
    try { localStorage.setItem(WALL_KEY, JSON.stringify(list.slice(0, 40))) } catch(error) { /* almacenamiento no disponible */ }
}
function renderWall()
{
    const list = loadWall()
    wallListEl.innerHTML = ''
    if(list.length === 0)
    {
        wallListEl.innerHTML = '<p class="wall-empty">Aún no hay rutas guardadas. ¡Sé el primero!</p>'
        return
    }
    for(const entry of list)
    {
        const card = document.createElement('article')
        card.className = 'wall-card'
        card.innerHTML = `<strong>${entry.names.join(' → ')}</strong>${entry.names.length} paradas`
        wallListEl.appendChild(card)
    }
}
function openWall() { renderWall(); wallEl.classList.add('is-on') }
function closeWall() { wallEl.classList.remove('is-on') }

shareFabEl.addEventListener('click', () =>
{
    const names = routeStops.map((id) => pointById.get(id)?.name).filter(Boolean)
    if(names.length >= 2) saveWallEntry({ names, date: Date.now() })
    openWall()
})
wallCloseEl.addEventListener('click', closeWall)
navWallEl.addEventListener('click', openWall)

function exitToTrio()
{
    closeWall()
    hideConfirm()
    closeCard()
    activeCategory = null
    subnavEl.classList.remove('is-on')
    worldEl.classList.remove('is-on')
    worldTintEl.classList.remove('is-on')
    routebarEl.classList.remove('is-on')
    shareFabEl.classList.remove('is-on')
    insideBulevar = false
    gsap.to(worldState, { enter: 0, duration: 1.1, ease: 'power2.inOut' })
    gsap.to(bulevar.group.scale, { x: 0.0001, y: 0.0001, z: 0.0001, duration: 0.8, ease: 'power1.in' })
    spawnCategoryTrio()
}

navBackEl.addEventListener('click', () =>
{
    if(wallEl.classList.contains('is-on')) { closeWall(); return }
    if(confirmEl.classList.contains('is-on')) { hideConfirm(); return }
    if(card3dEl.classList.contains('is-on')) { closeCard(); return }
    if(insideBulevar) exitToTrio()
})
navMenuEl.addEventListener('click', () =>
{
    if(insideBulevar) exitToTrio()
})
navRestartEl.addEventListener('click', () =>
{
    if(window.confirm('¿Reiniciar la experiencia desde el inicio?')) window.location.reload()
})

function spawnCategoryTrio()
{
    spawnTrio(CATEGORY_CHOICES, { x: WORLD_X, y: STAGE_Y }, {
        eyebrow: 'Aterrizaste en el bulevar',
        heading: '¿Por dónde quieres empezar?'
    }, enterCategory)
}

/**
 * Arrastrar para girar el Bulevar (con inercia) y tocar para seleccionar
 */
let worldRotY = 0
let worldRotVel = 0
let worldFocusRotY = null
let dragging = false
let dragMoved = false
let dragLastX = 0
let dragLastT = 0

canvas.addEventListener('pointerdown', (event) =>
{
    if(!insideBulevar && !trio) return
    dragging = true
    dragMoved = false
    dragLastX = event.clientX
    dragLastT = performance.now()
    worldRotVel = 0
    canvas.setPointerCapture(event.pointerId)
})

canvas.addEventListener('pointermove', (event) =>
{
    if(!dragging) return
    const dx = event.clientX - dragLastX
    if(Math.abs(dx) > 3) dragMoved = true
    const now = performance.now()
    const dt = Math.max(now - dragLastT, 1) / 1000
    if(insideBulevar)
    {
        const delta = (dx / sizes.width) * Math.PI * 1.6
        worldRotY += delta
        worldRotVel = delta / dt
        worldFocusRotY = null
    }
    dragLastX = event.clientX
    dragLastT = now
})

// Raycast directo en las coordenadas del evento: no depende de un pointermove
// previo, así que funciona igual con mouse, touch o un click simulado.
function pickAt(clientX, clientY, objects)
{
    const ndc = new THREE.Vector2((clientX / sizes.width) * 2 - 1, -(clientY / sizes.height) * 2 + 1)
    raycaster.setFromCamera(ndc, camera)
    return raycaster.intersectObjects(objects, true)[0] || null
}

function endDrag(event)
{
    if(!dragging) return
    dragging = false
    try { canvas.releasePointerCapture(event.pointerId) } catch(error) { /* noop */ }
    if(dragMoved) return

    if(trio)
    {
        const hit = pickAt(event.clientX, event.clientY, trio.islands)
        if(hit)
        {
            let obj = hit.object
            while(obj && obj.userData.trioIndex === undefined) obj = obj.parent
            if(obj) resolveTrio(obj.userData.trioIndex)
        }
        return
    }

    if(insideBulevar)
    {
        const hit = pickAt(event.clientX, event.clientY, visiblePinMeshes())
        if(hit) selectPin(hit.object.userData.pinRef.userData.id)
    }
}

function visiblePinMeshes()
{
    return pinMeshes.filter((mesh) => mesh.userData.pinRef.visible)
}
canvas.addEventListener('pointerup', endDrag)
canvas.addEventListener('pointercancel', endDrag)

canvas.addEventListener('wheel', (event) =>
{
    if(!insideBulevar) return
    event.preventDefault()
    worldRotVel += (event.deltaX + event.deltaY) * 0.0015
    worldFocusRotY = null
}, { passive: false })

/**
 * Proyección 3D → pantalla
 */
const projected = new THREE.Vector3()
function toScreen(x, y, z)
{
    projected.set(x, y, z).project(camera)
    return {
        x: (projected.x * 0.5 + 0.5) * sizes.width,
        y: (-projected.y * 0.5 + 0.5) * sizes.height
    }
}

/**
 * Loop
 */
const clock = new THREE.Clock()
let prevY = null
let prevCharX = 0
let walkPhase = 0
let walkAmount = 0
let nextBlink = 2
let lastActive = -1
let trioSpawned = false

const tick = () =>
{
    const dt = Math.min(clock.getDelta(), 0.05)
    const t = clock.elapsedTime
    const ambient = reduceMotion ? 0 : 1

    /**
     * Posición del personaje: horizontal en la carga, vertical en la historia
     */
    let charX = 0
    let charY = 0
    const drop = clamp(state.reveal / 0.55)
    if(mode === 'loading')
    {
        charX = state.loaderX
        charY = 0
    }
    else
    {
        charX = CHAR_X
        charY = lerp(TRAVEL_Y0, WALK_END, state.travel) - state.edge * EDGE_DROP
        if(state.fall > 0) charY = lerp(EDGE_Y, FALL_Y, state.fall)
        if(state.reveal > 0) charY = lerp(FALL_Y, STAGE_Y, easeOutBounce(drop))
    }
    const falling = state.fall > 0 && drop < 1
    const landed = drop >= 1

    if(prevY === null) prevY = charY
    const dy = charY - prevY
    prevY = charY
    const dx = charX - prevCharX
    prevCharX = charX
    const moveDelta = mode === 'loading' ? dx : dy
    const velocity = moveDelta / Math.max(dt, 0.001)

    // Ciclo de caminata ligado a la distancia recorrida
    const walkTarget = clamp(Math.abs(velocity) / 1.0)
    walkAmount = damp(walkAmount, walkTarget, 8, dt)
    walkPhase += Math.min(Math.abs(moveDelta) * 4.5, 0.6)

    // Hacia dónde mira: a la izquierda mientras camina a la carga,
    // volteado hacia la línea de tiempo (a su derecha) mientras la lee
    let targetRotY = mode === 'loading' ? -1.05 : 1.05
    targetRotY = lerp(targetRotY, 0, Math.max(state.look, falling ? 1 : 0, landed ? 1 : 0))
    character.root.rotation.y = damp(character.root.rotation.y, targetRotY, 6, dt)

    // Inclinación: mira hacia abajo en el borde, antes de caer
    let targetTilt = walkAmount > 0.3 && mode === 'loading' ? 0.05 : -0.05
    if(state.look > 0) targetTilt = lerp(targetTilt, 0.42, state.look)
    if(falling) targetTilt = -0.12
    if(landed) targetTilt = -0.05
    character.look.rotation.x = damp(character.look.rotation.x, targetTilt, 8, dt)

    // Piernas y brazos
    const flail = falling ? 1 : 0
    const swing = Math.sin(walkPhase)
    character.legs[0].rotation.x = swing * 0.65 * walkAmount + Math.sin(t * 16) * 0.45 * flail
    character.legs[1].rotation.x = -swing * 0.65 * walkAmount - Math.sin(t * 16) * 0.45 * flail
    const armsUp = smooth(0, 0.12, state.fall) * (landed ? 0 : 1)
    character.arms.forEach((arm, i) =>
    {
        const side = arm.userData.side
        arm.rotation.x = (i === 0 ? -swing : swing) * 0.5 * walkAmount
        const targetZ = side * (0.35 + armsUp * 2.3 + Math.sin(t * 14 + i) * 0.2 * flail)
        arm.rotation.z = damp(arm.rotation.z, targetZ, 12, dt)
    })

    // Rebote, respiración y aplastamiento al aterrizar
    const bounce = Math.abs(Math.sin(walkPhase)) * 0.07 * walkAmount
    const breath = Math.sin(t * 2.2) * 0.015 * ambient
    const squash = Math.sin(clamp((state.reveal - 0.5) / 0.25) * Math.PI) * 0.2
    character.pivot.position.y = bounce
    character.pivot.scale.set(1 + squash * 0.5, 1 + breath - squash, 1 + squash * 0.5)
    character.root.rotation.z = Math.sin(t * 7) * 0.12 * flail

    // Ojos: parpadeo y sorpresa
    nextBlink -= dt
    const blinking = nextBlink < 0.12
    if(nextBlink < 0) nextBlink = 2.5 + Math.random() * 2.5
    const surprise = 1 + smooth(0.2, 0.6, state.look) * 0.35 * (falling || landed ? 0.6 : 1)
    character.eyes.forEach((eye) =>
    {
        eye.scale.set(surprise, blinking ? 0.12 : surprise, 0.45)
    })
    character.sprout.rotation.z = Math.sin(t * 3) * 0.08 * ambient + Math.sin(t * 20) * 0.3 * flail

    character.root.position.set(charX, charY, CHAR_Z)
    // Se desvanece detrás de las nubes y ya no vuelve a aparecer
    character.root.visible = state.cover < 0.9

    // Sombra (solo mientras camina la línea de tiempo)
    if(mode !== 'loading' && !falling && !landed)
    {
        shadow.visible = true
        shadow.position.set(charX, charY - 0.5, CHAR_Z + 0.02)
        shadow.material.opacity = 0.16
        shadow.scale.setScalar(0.9)
    }
    else
    {
        shadow.visible = false
    }

    /**
     * Marcadores: van apareciendo a medida que el personaje se acerca
     */
    const lineTip = LINE_TOP - line.scale.y * LINE_LENGTH
    markers.forEach((marker, i) =>
    {
        const distanceAhead = charY - hitoY[i]
        const near = smooth(10, 6, distanceAhead)
        const reached = clamp((hitoY[i] - lineTip) / 1.5)
        markerAppear[i] = mode === 'loading' ? 0 : near * reached
        marker.scale.setScalar(Math.max(0.0001, easeOutBack(markerAppear[i])))
        marker.userData.knob.position.y = 0.06 + Math.sin(t * 2 + i) * 0.04 * ambient
    })

    /**
     * Cámara
     */
    const LOOK_AHEAD = 0.9
    let camX = mode === 'loading' ? framing.offset : 0
    let lookAtY = mode === 'loading' ? 1.5 : charY - LOOK_AHEAD * (1 - state.edge * 0.4)
    let dist = (mode === 'loading' ? framing.dist : framing.readDist) * (1 - 0.22 * state.edge)
    let rise = mode === 'loading' ? 0.9 : 1.3

    const fallBlend = smooth(0, 0.5, state.fall)
    rise = lerp(rise, 7.5, fallBlend)
    dist = lerp(dist, framing.readDist * 1.35, fallBlend)

    const toStage = smooth(0, 0.85, state.reveal)
    lookAtY = lerp(lookAtY, STAGE_Y - 0.6, toStage)
    dist = lerp(dist, framing.trioDist, toStage)
    rise = lerp(rise, 3.2, toStage)

    const toWorld = smooth(0, 1, worldState.enter)
    lookAtY = lerp(lookAtY, WORLD_Y, toWorld)
    dist = lerp(dist, framing.worldDist, toWorld)
    rise = lerp(rise, 4.4, toWorld)

    camera.position.set(camX, lookAtY + rise, dist)
    camera.lookAt(camX, lookAtY, 0)
    scene.fog.near = dist + 6
    scene.fog.far = dist + 42

    // Decoración flotando
    for(const item of decor)
    {
        if(item.userData.baseY !== undefined) item.position.y = item.userData.baseY + Math.sin(t * 0.5 + item.userData.phase) * 0.2 * ambient
        if(item.userData.baseX !== undefined) item.position.x = item.userData.baseX + Math.sin(t * 0.15 + item.userData.phase) * 0.6 * ambient
    }

    // Aparecen las tres opciones una sola vez, al llegar al final de la caída
    if(!trioSpawned && state.reveal > 0.6)
    {
        trioSpawned = true
        spawnCategoryTrio()
    }

    // El Bulevar 3D: giro con inercia y pines
    if(worldFocusRotY !== null)
    {
        worldRotY = damp(worldRotY, worldFocusRotY, 4, dt)
        worldRotVel = 0
    }
    else if(!dragging)
    {
        worldRotVel = damp(worldRotVel, 0, 3, dt)
        worldRotY += worldRotVel * dt
    }
    bulevar.group.rotation.y = worldRotY

    // Cada categoría muestra solo sus propios puntos; Rutas los muestra todos
    // porque conecta lugares y eventos entre sí.
    bulevar.pins.forEach((pin) =>
    {
        const matches = !activeCategory || activeCategory === 'rutas' || activeCategory === pin.userData.category
        pin.visible = matches
        if(!matches) return

        const isSelected = pin.userData.id === selectedPinId
        const isHover = pin.userData.id === pinHoverId
        const targetScale = isSelected ? 1.4 : isHover ? 1.15 : 1
        pin.userData.animScale = damp(pin.userData.animScale ?? 1, targetScale, 10, dt)
        pin.scale.setScalar(pin.userData.animScale)
        pin.position.y = Math.sin(t * 2 + pin.userData.phase) * 0.05 * ambient
        pin.userData.ring.rotation.z = t * 0.5
        pin.userData.glow.material.opacity = 0.14 + (isSelected || isHover ? 0.2 : 0) + Math.sin(t * 3 + pin.userData.phase) * 0.03
    })

    /**
     * HTML
     */
    // Intro y barra de años
    introEl.style.opacity = state.intro * (1 - smooth(0, 0.035, state.travel))
    introEl.style.transform = `translateY(${-state.travel * 600}px)`
    railEl.style.opacity = state.intro * (1 - smooth(0, 0.5, state.edge))
    railFillEl.style.transform = `scaleY(${state.travel})`

    // Tarjetas de hitos
    let activeIndex = -1
    let bestDistance = SPACING_Y * 0.55
    hitoY.forEach((y, i) =>
    {
        const d = Math.abs(y - charY)
        if(d < bestDistance)
        {
            bestDistance = d
            activeIndex = i
        }
    })

    cards.forEach((card, i) =>
    {
        const appear = markerAppear[i]
        if(appear < 0.01 || state.look > 0.99)
        {
            card.el.style.opacity = 0
            return
        }
        const side = markers[i].userData.side
        const p = toScreen(side * CARD_X, hitoY[i] + 0.35, MARKER_Z)
        const edgeFade = smooth(-card.width * 0.3, card.width * 0.5, p.x) * smooth(sizes.width + card.width * 0.3, sizes.width - card.width * 0.5, p.x)
        card.el.style.opacity = appear * edgeFade * (1 - state.look)
        card.el.style.transform = `translate3d(${p.x - card.width / 2}px, ${p.y - card.height - 14 + (1 - appear) * 24}px, 0)`
        const isActive = i === activeIndex
        if(isActive !== card.active)
        {
            card.active = isActive
            card.el.classList.toggle('is-active', isActive)
        }
    })

    if(activeIndex !== lastActive)
    {
        railYears.forEach((li, i) => li.classList.toggle('is-on', i <= activeIndex))
        lastActive = activeIndex
    }

    // "!" sobre la cabeza
    const alertAlpha = smooth(0.25, 0.5, state.look) * (1 - smooth(0, 0.12, state.fall))
    alertEl.style.opacity = alertAlpha
    if(alertAlpha > 0)
    {
        const p = toScreen(charX, charY + 2.05, CHAR_Z)
        const pop = 0.6 + easeOutBack(smooth(0.25, 0.55, state.look)) * 0.4
        alertEl.style.transform = `translate3d(${p.x - 10}px, ${p.y - 70}px, 0) scale(${pop}) rotate(${Math.sin(t * 10) * 4}deg)`
    }

    // Nubes
    const cloudsOn = state.cover > 0 && state.reveal < 1
    cloudsEl.style.visibility = cloudsOn ? 'visible' : 'hidden'
    if(cloudsOn)
    {
        for(const cloud of clouds2D)
        {
            const c = smooth(0, 1, (state.cover - cloud.delay) / (1 - 0.3))
            const r = smooth(0, 1, (state.reveal - cloud.delay * 0.6) / 0.8)
            const targetX = cloud.tx * sizes.width
            const targetY = cloud.ty * sizes.height
            let x = targetX
            let y = targetY + (1 - c) * sizes.height * cloud.drop
            x += r * cloud.side * sizes.width * 0.95
            y -= r * sizes.height * 0.35
            const scale = 1 + r * 0.25
            cloud.el.style.transform = `translate3d(${x - cloud.w / 2}px, ${y - cloud.h / 2}px, 0) scale(${scale})`
        }
        veilEl.style.opacity = smooth(0.55, 1, state.cover) * (1 - smooth(0, 0.3, state.reveal))
    }

    // Trío activo: el título y las etiquetas solo se ven mientras el trío
    // existe Y el scroll realmente está en esa etapa (si el usuario vuelve a
    // subir, deben desaparecer igual que las islas 3D)
    trioEl.classList.toggle('is-on', !!trio && state.reveal > 0.55)

    trioHoverIndex = -1
    if(trio)
    {
        raycaster.setFromCamera(pointer, camera)
        const hit = raycaster.intersectObjects(trio.islands, true)[0]
        if(hit)
        {
            let obj = hit.object
            while(obj && obj.userData.trioIndex === undefined) obj = obj.parent
            if(obj) trioHoverIndex = obj.userData.trioIndex
        }

        trio.islands.forEach((island, i) =>
        {
            island.position.y = TRIO_LAYOUT[i][1] + Math.sin(t * 0.9 + i * 1.7) * 0.1 * ambient
            const target = trioHoverIndex === i ? 1 : 0
            island.userData.hover = damp(island.userData.hover, target, 8, dt)
            const s = island.scale.x
            if(s > 0.5) island.scale.setScalar(s) // no pisar la animación de resolución
            const worldPos = new THREE.Vector3()
            island.getWorldPosition(worldPos)
            const p = toScreen(worldPos.x, worldPos.y + 2.4, worldPos.z)
            const label = trio.labelEls[i]
            label.style.transform = `translate3d(${p.x}px, ${p.y}px, 0)`
            label.classList.toggle('is-on', true)
        })
    }

    // Raycast sobre los puntos del bulevar
    pinHoverId = null
    if(insideBulevar && worldState.enter > 0.9 && !trio)
    {
        raycaster.setFromCamera(pointer, camera)
        const hit = raycaster.intersectObjects(visiblePinMeshes())[0]
        if(hit) pinHoverId = hit.object.userData.pinRef.userData.id
    }
    canvas.style.cursor = (pinHoverId || (trio && trioHoverIndex >= 0)) ? 'pointer' : (insideBulevar ? 'grab' : '')

    renderer.render(scene, camera)
    window.requestAnimationFrame(tick)
}

tick()
startLoader()
